import{_ as a,o as e,c as d,a3 as r}from"./chunks/framework.DxEvSMU4.js";const b=JSON.parse('{"title":"應用範例","description":"","frontmatter":{},"headers":[],"relativePath":"examples/index.md","filePath":"examples/index.md","lastUpdated":1793023679000}'),o={name:"examples/index.md"};function l(n,t,i,s,h,p){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="應用範例" tabindex="-1">應用範例 <a class="header-anchor" href="#應用範例" aria-label="Permalink to &quot;應用範例&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本頁屬性</p><ul><li>等級: ○ 依情境</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: 各範例的設定與指令依官方文件整理, 未實機驗證; 各頁的「待查證」列出個別事項; 本頁為索引, 來源見各範例頁與頁尾「資料來源」</li></ul></div><p><strong>結論</strong>: 範例說明組好的系統能解決哪些日常問題, 以及每個範例至少要組到哪些模組. 個人範例組到里程碑 1 或加上檢索即可; 企業範例多數需要里程碑 2, 會讓模型動手的範例才需要里程碑 3. 所有範例共用同一個原則: 模型負責整理與撰寫; 需要精確結果的工作 (計算數字, 找出文件差異) 交給程式; 會改變系統狀態或對外的動作由人確認.</p><table tabindex="0"><thead><tr><th>範例</th><th>對象</th><th>需要的模組</th><th>解決的問題</th></tr></thead><tbody><tr><td><a href="/lanai-handbook/examples/p1-docs-qa">P1 問自己的文件</a></td><td>個人</td><td>M1, M2, M4</td><td>把個人筆記, 手冊, 論文放進知識庫, 用自然語言提問並取得附出處的回答</td></tr><tr><td><a href="/lanai-handbook/examples/p2-coding">P2 程式撰寫助理</a></td><td>個人</td><td>M1, M2 (需要執行程式時加 M7)</td><td>在本機請模型解釋, 撰寫與檢查程式碼, 程式碼不離開本機</td></tr><tr><td><a href="/lanai-handbook/examples/p3-meeting-notes">P3 會議記錄摘要</a></td><td>個人</td><td>M1, M2</td><td>把逐字稿整理成摘要, 決議與待辦清單</td></tr><tr><td><a href="/lanai-handbook/examples/e1-knowledge-base">E1 內部知識庫問答</a></td><td>企業</td><td>M0 至 M6</td><td>讓同事依權限查詢內部規章, 手冊與歷史文件</td></tr><tr><td><a href="/lanai-handbook/examples/e2-alert-triage">E2 資安告警分流</a></td><td>企業</td><td>M0 至 M8</td><td>由隔離模型整理告警內容, 代理依政策建議或執行處置, 高風險動作轉人工核准</td></tr><tr><td><a href="/lanai-handbook/examples/e3-document-compare">E3 合約與法規文件比對</a></td><td>企業</td><td>M0 至 M6</td><td>比對合約版本差異, 或把內部文件對照法規條文, 列出差異與出處</td></tr><tr><td><a href="/lanai-handbook/examples/e4-weekly-report">E4 每週報告自動化</a></td><td>企業</td><td>M0 至 M7, M9</td><td>由 n8n 定期彙整工作紀錄與指標, 交給模型撰寫週報草稿, 經人工確認後寄出</td></tr><tr><td><a href="/lanai-handbook/examples/e5-multi-agent-investigation">E5 多代理事件調查</a></td><td>企業</td><td>M0 至 M8</td><td>三個專責代理平行查 SIEM, EDR 與情資平台, 彙整代理撰寫調查報告並提出處置建議, 高風險動作轉人工核准</td></tr></tbody></table><p>每個範例依同一個格式撰寫: 情境, 需要的模組, 流程, 設定要點, 驗收方式, 風險與限制. 「需要的模組」一節標出每個模組屬於哪個里程碑; 「驗收方式」列出上線前可以照著做的測試題或檢核步驟.</p><h2 id="閱讀建議" tabindex="-1">閱讀建議 <a class="header-anchor" href="#閱讀建議" aria-label="Permalink to &quot;閱讀建議&quot;">​</a></h2><ul><li><strong>沒有工程背景的個人讀者</strong>: 從 P1 或 P3 開始. 兩者都只需要里程碑 1 的環境 (P1 另加 M4 的檢索), 不需要閘道, 帳號系統或代理.</li><li><strong>寫程式的個人讀者</strong>: P2 說明三種用法, 只有讓模型執行程式碼時才需要 M7 的沙箱.</li><li><strong>規劃企業導入的 IT 與資安人員</strong>: 先讀 E1, 它定義了部門, 群組與知識庫的權限模型, E3 沿用同一套設計. E2 與 E4 會讓系統動手做事, 分別示範代理加政策引擎, 以及固定流程加人工核准兩種做法. E5 在 E2 之上示範多代理: 多個代理平行調查, 各有自己的權限, 結果經程式檢查後才交給下一個代理, 建議讀完 E2 再讀.</li><li><strong>E4 的模組備註</strong>: M9 的前置模組包含 M7. E4 只用到 M7 的工具閘道 (MCP gateway), 不需要程式碼沙箱.</li></ul><table tabindex="0"><thead><tr><th>範例</th><th>會改變系統狀態或對外的動作</th><th>人工確認的位置</th></tr></thead><tbody><tr><td>P1, P3</td><td>無</td><td>讀者引用回答或寄出會議記錄前, 核對原文</td></tr><tr><td>P2</td><td>用法 C 會修改檔案與執行指令</td><td>合併程式碼前檢查差異</td></tr><tr><td>E1, E3</td><td>無 (只查詢與整理)</td><td>涉及權益或法律判斷時, 由承辦單位或專業人員確認</td></tr><tr><td>E2</td><td>開工單, 隔離主機, 封鎖 IP 等</td><td>A2 審查不一致與所有 A3 動作由分析師核准</td></tr><tr><td>E4</td><td>寄送週報</td><td>每份草稿寄出前由負責人核准, 對外發信屬 A3</td></tr><tr><td>E5</td><td>開工單, 隔離主機</td><td>同 E2; 另由分析師確認調查報告定稿與結案</td></tr></tbody></table><p>由上表可見, 範例越往後, 系統能直接做的事越多, 人工確認的位置也越需要事先設計清楚; 動作分級 A0 至 A3 的定義見 E2.</p><h2 id="資料來源" tabindex="-1">資料來源 <a class="header-anchor" href="#資料來源" aria-label="Permalink to &quot;資料來源&quot;">​</a></h2><p>本頁是第三部的索引與閱讀建議, 內容由整理者依下列頁面彙整, 沒有引用外部統計或市場資料.</p><ul><li><strong>範例與模組對應, 里程碑對應</strong>: 整理自 <a href="/lanai-handbook/examples/p1-docs-qa">P1</a>, <a href="/lanai-handbook/examples/p2-coding">P2</a>, <a href="/lanai-handbook/examples/p3-meeting-notes">P3</a>, <a href="/lanai-handbook/examples/e1-knowledge-base">E1</a>, <a href="/lanai-handbook/examples/e2-alert-triage">E2</a>, <a href="/lanai-handbook/examples/e3-document-compare">E3</a>, <a href="/lanai-handbook/examples/e4-weekly-report">E4</a>, <a href="/lanai-handbook/examples/e5-multi-agent-investigation">E5</a> 各頁的「需要的模組」一節, 與<a href="/lanai-handbook/build/overview">組裝總覽</a>的里程碑定義. 各範例的事實與來源列在該頁的「參考來源」.</li><li><strong>共用原則</strong> (模型負責整理與撰寫; 需要精確結果的工作交給程式; 改變系統狀態或對外的動作由人確認): 屬整理者的設計原則 (推論, 信心: 中). 其中「高風險動作由人確認」與 OWASP GenAI LLM01:2025 的緩解方向一致, 該頁建議對特權操作加入人工核准, 並把模型權限限制在最小必要範圍. <a href="https://genai.owasp.org/llmrisk/llm01-prompt-injection/" target="_blank" rel="noreferrer">OWASP GenAI: LLM01 Prompt Injection</a></li><li><strong>「人工確認的位置」表與動作分級 A0 至 A3</strong>: 整理者設計, 定義見 <a href="/lanai-handbook/examples/e2-alert-triage">E2</a>. E2 引用的 2026-10 藍隊代理模擬屬內部研究紀錄 (內部模擬, 推論), 非公開來源, 沒有公開佐證.</li></ul>',12)])])}const c=a(o,[["render",l]]);export{b as __pageData,c as default};
